import React, { useState } from "react";
import axios from "../utils/axios";
import toast from "react-hot-toast";

const AddExpenseForm = ({ budgetId, onExpenseAdded }) => {
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");
  const [date, setDate] = useState(() => new Date().toISOString().split("T")[0]);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await axios.post(
        `/api/budgets/${budgetId}/expenses`,
        {
          description,
          amount: parseFloat(amount),
          date,
        },
        {
          headers: {
            "Content-Type": "application/json",
            email: localStorage.getItem("email"),
          },
        }
      );

      setDescription("");
      setAmount("");
      setDate(new Date().toISOString().split("T")[0]);

      toast.success("Expense added!");
      onExpenseAdded();
    } catch (err) {
      console.error("Failed to add expense", err);
      toast.error("Failed to add expense");
    } finally {
      setLoading(false);
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      className="bg-white p-4 rounded-xl shadow-md flex flex-col gap-4"
    >
      <h2 className="text-xl font-semibold">Add Expense</h2>

      <label className="flex flex-col text-sm font-medium text-gray-700">
        Expense Name:
        <input
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          className="border p-2 rounded mt-1"
          required
        />
      </label>

      <label className="flex flex-col text-sm font-medium text-gray-700">
        Amount (RM):
        <input
          type="number"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          className="border p-2 rounded mt-1"
          required
          min="0"
          step="0.01"
        />
      </label>

      <label className="flex flex-col text-sm font-medium text-gray-700">
        Date:
        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          className="border p-2 rounded mt-1"
          required
        />
      </label>

      <button
        type="submit"
        disabled={loading}
        className="bg-indigo-500 text-white py-2 rounded hover:bg-indigo-600 disabled:opacity-60"
      >
        {loading ? "Adding..." : "Add"}
      </button>
    </form>
  );
};

export default AddExpenseForm;
